    "#================================================#\n",
    "# Turning\n",
    "#================================================#\n",
    "function turn_condition(W_S, V, R, phi, CD0, K)\n",
    "    q = 0.5 * rho_sl * sigma_cruise * V^2\n",
    "    \n",
    "    n = 1 / cos(phi)\n",
    "\n",
    "    CL_turn = n * W_S / q\n",
    "    \n",
    "    CD_turn = CD0 + K * CL_turn^2\n",
    "    T_W = CD_turn * q / W_S\n",
    "    \n",
    "    return T_W\n",
    "end\n",
    "begin\n",
    "    TbW_turn = turn_condition.(wing_loading, V_Cruise, turn_radius, bank_angle, CD0_cruise, K_cruise)\n",
    "end\n"
   ]
  },
